if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
tower=bpy.data.objects.get('V4 | torre documental'); hall=bpy.data.objects.get('V4 | hall piso terreo marcador'); door=bpy.data.objects.get('V4 | porta entrada placeholder')
if not tower or not hall or not door: raise RuntimeError('anchors V4 ausentes')
T=tower.matrix_world.translation.xy.copy(); D=door.matrix_world.translation.xy.copy(); EX=(hall.matrix_world.translation.xy-T).normalized(); EY=Vector((-EX.y,EX.x))
def points2(o):
    if o.type=='MESH' and o.data and len(o.data.vertices): return [(o.matrix_world@v.co).xy for v in o.data.vertices]
    if o.type=='CURVE' and o.data:
        out=[]
        for sp in o.data.splines:
            if len(sp.bezier_points): out.extend([(o.matrix_world@bp.co).xy for bp in sp.bezier_points])
            else: out.extend([(o.matrix_world@Vector((p.co.x,p.co.y,p.co.z))).xy for p in sp.points])
        if out:return out
    try:return [(o.matrix_world@Vector(c)).xy for c in o.bound_box]
    except:return [o.matrix_world.translation.xy.copy()]
def rec(o):
    pp=points2(o); dt=min((p-T).length for p in pp); dd=min((p-D).length for p in pp);
    ss=[(p-T).dot(EX) for p in pp]; ll=[(p-T).dot(EY) for p in pp]
    tags=str(o.get('osm_tags','')); nm=o.name
    return {'name':nm,'type':o.type,'osm_id':str(o.get('osm_id','')),'dist_to_tower_m':round(dt,3),'dist_to_upper_door_m':round(dd,3),'s_range':[round(min(ss),3),round(max(ss),3)],'l_range':[round(min(ll),3),round(max(ll),3)],'collections':[c.name for c in o.users_collection],'osm_tags':tags[:700],'fonte':str(o.get('fonte',''))}
rows=[]; named=[]
for o in bpy.data.objects:
    if o.type not in ('MESH','CURVE'): continue
    has_osm=('osm_id' in o) or ('osm_tags' in o)
    if not has_osm: continue
    r=rec(o)
    if r['dist_to_tower_m']<=120 or r['dist_to_upper_door_m']<=120: rows.append(r)
    txt=(o.name+' '+str(o.get('osm_tags',''))).lower()
    if 'lacerda' in txt or 'elevador' in txt or 'elevator' in txt: named.append(r)
rows_t=sorted(rows,key=lambda r:(r['dist_to_tower_m'],r['dist_to_upper_door_m']))[:40]
rows_d=sorted(rows,key=lambda r:(r['dist_to_upper_door_m'],r['dist_to_tower_m']))[:40]
res={'tower_xy':[round(T.x,3),round(T.y,3)],'door_xy':[round(D.x,3),round(D.y,3)],'near_tower_top40':rows_t,'near_upper_door_top40':rows_d,'name_tag_matches':sorted(named,key=lambda r:r['dist_to_tower_m'])[:40]}
print('NEAREST_OSM_LACERDA_V4_BEGIN'); print(json.dumps(res,ensure_ascii=False,separators=(',',':'))); print('NEAREST_OSM_LACERDA_V4_END')
